resources.string_upd:
{email_header}
<p>Hello, {client_name}.</p>
<p>You've purchased <a href="{bundle_url}">{bundle_title}</a> credits bundle.<br />Your order is <b>{order}</b>.</p>
<p>{notes}</p>
{email_footer}

{email_header}
<p><a href="{profile_link}">{profile_name}</a> requested to withdraw <b>{amount}</b> credits from his/her balance.</p>
<p>Current withdrawal conversion rate is <b>{rate}</b></p>
<p>Withdrawal can be confirmed <a href="{confirm_url}">here</a>.</p>
<p>Notes from <b>{profile_name}</b>:<br />{message}</p>
{email_footer}

{email_header}
<p><a href="{profile_link}">{profile_name}</a> canceled his/her withdrawal request for <b>{amount}</b> credits.</p>
<p>The canceled withdrawal request can be seen <a href="{manage_url}">here</a>.</p>
{email_footer}

{email_header}
<p>Hello, {profile_name}.</p>
<p>The requested amount of credits (<b>{amount}</b>) was withdrawn to you.</p>
{email_footer}
